"""Three-page handout built from the preserved results, without API calls."""
import json
from pathlib import Path
from pypdf import PdfReader
from report_utils import render_report

ROOT=Path(__file__).resolve().parents[1]


def main():
    r=json.loads((ROOT/'artifacts/runs/robustness_study_2026-11-23_v1/analysis.json').read_text(encoding='utf-8'))
    pages=[]
    def page(title):s=[('h1',title)];pages.append(s);return s
    def p(s,text):s.append(('p',text))
    def h(s,text):s.append(('h2',text))
    def table(s,headers,rows,widths):s.append(('table',(headers,rows,widths)))
    s=page('Минимальный прототип коллективных предпочтений')
    p(s,'Краткая выжимка для сдачи. 25.11.2026. Эксперименты выполнены 21-23.11.2026. Идея: исследовать совместное влияние внешней информации, общения и истории наблюдений на предпочтения участников и показатели сообщества.')
    h(s,'Что реализовано')
    p(s,'Concordia 2.4.0: шесть вымышленных участников выбирают между цифровым доступом (+1) и печатными книгами (-1) в библиотеке. Четыре раунда, кольцо контактов, разные исходные позиции и доверие источнику. Агенты получают наблюдения и возвращают opinion и message. Реальная LLM - bonsai2-27b через предоставленный OpenAI-совместимый шлюз.')
    table(s,['Объём','Подтверждённый результат'],[
        ['Реальная LLM','534 генерации; 217 405 токенов по usage'],
        ['Численный контроль','40 основных запусков и две длинные пробы памяти'],
        ['Проверка кода','27 автоматических тестов'],
        ['Точный повтор','Четыре симуляции: совпали траектории и 96 текстов ответов']],[.31,.69])
    h(s,'Основные результаты')
    p(s,'Прототип работает, но повторяемость одной конфигурации не означает устойчивости социального вывода. Общение дало следующие изменения дисперсии относительно контроля с теми же профилями:')
    table(s,['Набор профилей','Опыт минус контроль','Направление'],[
        [str(x['seed']),f"{x['variance_minus_control']:+.4f}",'Разброс выше' if x['variance_minus_control']>0 else 'Разброс ниже']
        for x in r['paired_profile_contrasts'] if x['condition']=='peers_only'],[.29,.34,.37])
    p(s,'При seed=11 длинное окно без собственного поля initial_opinion дало дисперсию 0.2011 против 0.3189 в базовом варианте. Средний модуль изменения позиции - 0.1210 против 0.0711. Отдельные изменения не дали такого же результата: важна их комбинация. Это опыт одного набора профилей, который нужно повторять.')
    p(s,'В роли участника симуляции модель решила 11 из 12 простых задач; арифметическая ошибка воспроизводилась. В проверенных нейтральных/reasoning-пробах она исчезала. Вычисления и метрики выполняются кодом; формат JSON не считается доказательством правильности ответа.')

    s=page('Устройство, ограничения и полезные решения')
    table(s,['Слой','Реализация'],[
        ['Агент','EntityAgent и компоненты Concordia; профиль и текущая позиция в своём DecisionContext'],
        ['Память','ListMemory и ObservationToMemory; извлечение внешних наблюдений за 1 или 4 раунда'],
        ['Решение','ConcatActComponent собирает контекст; LanguageModel вызывает заглушку либо LLM API'],
        ['Среда','Свой граф, новость, доставка событий и синхронный планировщик; стандартный Game Master не использовался'],
        ['Взаимодействие','Снимок предыдущего раунда доставляется соседям до новых действий; сохраняются тексты и позиции']],[.24,.76])
    h(s,'Что ограничивает выводы')
    p(s,'Одна LLM и один сценарий; всего шесть агентов и четыре раунда. Три seed меняют числа, но сохраняют роли и их порядок. Факторный опыт памяти выполнен только на seed=11. Поэтому роль и исходная позиция пока не разделены как причины.')
    p(s,'Общение передаёт текст вместе с численной позицией. Память содержит внешние наблюдения; собственные старые аргументы автоматически не возвращаются. Длинное окно снова предъявляет старые сообщения. Удаление initial_opinion не удаляет текущую позицию или всю информацию о первоначальном состоянии.')
    p(s,'Нет второй модели, сравнения с людьми или эмпирическими данными. Статистическая значимость и научная новизна не заявляются. Дисперсия сама по себе не доказывает поляризацию. Денежная стоимость неизвестна без тарифа; фактические токены и время сохранены.')
    h(s,'Что полезно своей библиотеке')
    p(s,'Компонентный агент; единый интерфейс заглушки и LLM; раздельные хранение, извлечение и сборка контекста; явные события и фазы исполнения; конфигурации факторов, точные журналы, snapshots, проверка JSON и лимиты запросов. Полезно сохранять частичные результаты и анализировать парные условия с одинаковыми профилями.')
    p(s,'В прототипе не хватает собственной истории аргументов, памяти отношений и источников, динамического доверия, изменяемых контактов и общего исследовательского слоя. Следующий шаг - перестановка ролей между позициями, общение без численных самооценок и проверка ключевых эффектов другой LLM.')
    h(s,'Сложность проведения')
    p(s,'Интеграция после настройки - 2/5; сопоставимость промптов и памяти - 3/5; интерпретация - 4/5. Возникали сетевые ограничения установки, различия API модулей, лимиты шлюза и рост контекста. Человеко-часы не измерялись. Детальный протокол и оценки находятся в полном отчёте.')

    s=page('Основные вопросы и короткие ответы')
    qa=[
        ('Почему Concordia?','Компоненты позволяют отдельно менять память, контекст и модель. Другие фреймворки просмотрены по документации; сравнительный запуск не проводился.'),
        ('Что здесь настоящее, а что написано самостоятельно?','Агенты и компоненты - Concordia. Среда и расписание - свои. LLM-запуски реальные; заглушка и записи явно отделены.'),
        ('Как устроена память?','Хранятся внешние наблюдения. Окно ограничивает их попадание в промпт, а не очищает хранилище. Собственная история аргументов пока не реализована.'),
        ('Почему не GPT-Luna через Codex?','Это был необязательный вариант ТЗ. Доступ к LLM обеспечен предоставленным шлюзом. Подключение GPT-Luna отдельно не проверялось.'),
        ('LLM достаточно хороша?','Для прототипа - с проверками. Есть вычислительная ошибка и чувствительность к контексту. Это не основание доверять ей расчёты или выводы о людях.'),
        ('Почему агенты не сменили сторону?','В коротких опытах менялась сила предпочтений. Отсутствие переходов за четыре раунда не доказывает долгосрочную устойчивость сообщества.'),
        ('Где коллективный результат?','Меняются среднее, разброс и несогласие соседей. Эффекты зависят от профилей и промпта; направление не универсально.'),
        ('Можно ли считать это научным результатом о людях?','Пока нет. Это проверка реализуемости и чувствительности стенда. Нужны чёткие гипотезы, независимая проверка и реальные данные.'),
        ('Как воспроизвести и показать?','Открыть demo/replay.html для записанных реальных ответов. Выполнить python scripts/demo.py --offline для нового локального запуска с заглушкой. Ни один режим не обращается к API.'),
        ('Что сохранено и где подробнее?','Конфигурации, графы, наблюдения, промпты, ответы, usage, checkpoints и код - в artifacts/. Полный отчёт: reports/complete_lab_report.pdf, 43 страницы. План показа: docs/DEMO.md.'),
    ]
    for i,(q,a) in enumerate(qa,1):p(s,f'{i}. {q} {a}')
    render_report(pages,ROOT/'reports','submission_brief','Краткая выжимка лабораторного прототипа',
        'Коллективные предпочтения | Выжимка для сдачи | 25.11.2026')
    count=len(PdfReader(ROOT/'reports/submission_brief.pdf').pages)
    if count!=3:raise ValueError(f'Expected three handout pages, got {count}; inspect layout')
    print(json.dumps({'pages':count,'new_api_calls':0}))


if __name__=='__main__':main()
